INSERT INTO `categories` VALUES (1,NULL,'PET bottles','pet-bottles','/vikaas_inputs/thumbnails/THUMBNAIL_PET_BOTTLES.webp','/vikaas_inputs/PHARMA_BOTTLES.webp','Precision injection blow-moulded PET bottles from 10ml to 1,000ml in cylindrical, Boston, dome, oval, and custom configurations.',1,'published','2026-09-14 14:54:00'),(2,NULL,'HDPE bottles','hdpe-bottles','/vikaas_inputs/thumbnails/THUMBNAIL_PET_BOTTLES.webp','/vikaas_inputs/PHARMA_BOTTLES.webp','Chemical-resistant HDPE containers engineered for pharmaceutical syrups, laboratory reagents, and industrial applications.',2,'published','2026-09-14 14:54:00'),(3,NULL,'Caps','caps','/vikaas_inputs/thumbnails/thumbnail_caps_and_closures.webp','/vikaas_inputs/COSMETICS.webp','Engineered screw closures, flip top caps, disc top caps, child-resistant caps (CRC), and tamper-evident ROPP finishes.',3,'published','2026-09-14 14:54:00'),(4,NULL,'Pumps','pumps','/vikaas_inputs/thumbnails/thumbnail_pumps.webp','/vikaas_inputs/COSMETICS.webp','Cosmetic lotion pumps, treatment dispensers, and saddle pumps with precision 1.2cc to 4.0cc dosage outputs.',4,'published','2026-09-14 14:54:00'),(5,NULL,'Finger sprayer','finger-sprayers','/vikaas_inputs/thumbnails/thumbnail_sprays.webp','/vikaas_inputs/COSMETICS.webp','Ultra-fine atomization mist sprayers with protective clear overcaps for toners, fragrances, and antiseptic formulations.',5,'published','2026-09-14 14:54:00'),(6,NULL,'Trigger sprayer','trigger-sprayers','/vikaas_inputs/thumbnails/thumbnail_sprays.webp','/vikaas_inputs/AGRO_PESTICIDES.webp','Heavy-duty ergonomic trigger sprayers and chemical-resistant industrial spray heads with stream and mist options.',6,'published','2026-09-14 14:54:00'),(7,NULL,'PET jars','pet-jars','/vikaas_inputs/thumbnails/thumbnail_NUTRACEUTICLE_JARS.webp','/vikaas_inputs/PET_nutraceuticle_jars.webp','Nutraceutical tablet jars, wide-mouth capsule containers, and cosmetic cream jars from 75cc to 500cc.',7,'published','2026-09-14 14:54:00'),(8,NULL,'Lids','lids','/vikaas_inputs/thumbnails/thumbnail_caps_and_closures.webp','/vikaas_inputs/COSMETICS.webp','Aluminum metal unishell lids, smooth ribbed screw caps, and induction heat-seal closures.',8,'published','2026-09-14 14:54:00'),(9,NULL,'PP jars','pp-jars','/vikaas_inputs/thumbnails/thumbnail_NUTRACEUTICLE_JARS.webp','/vikaas_inputs/PET_nutraceuticle_jars.webp','Double-wall luxury cosmetic jars and single-wall polypropylene jars with airtight interior shives.',9,'published','2026-09-14 14:54:00'),(10,NULL,'Mono material jar','mono-material-jars','/vikaas_inputs/PET_nutraceuticle_jars.webp','/vikaas_inputs/COSMETICS.webp','100% single-polymer recyclable PP jars aligned with circular packaging and ESG standards.',10,'published','2026-09-14 14:54:00'),(11,NULL,'Foamer pumps','foamer-pumps','/vikaas_inputs/thumbnails/thumbnail_pumps.webp','/vikaas_inputs/COSMETICS.webp','Propellant-free foaming dispenser bottles creating rich micro-foam for face washes and dermatological scrubs.',11,'published','2026-09-14 14:54:00'),(12,NULL,'Airless','airless','/vikaas_inputs/thumbnails/thumbnail_pumps.webp','/vikaas_inputs/COSMETICS.webp','Piston-driven vacuum airless bottles and bulb active dispensers protecting sensitive cosmetics from oxidation.',12,'published','2026-09-14 14:54:00');
